ON CONFLICT (source_domain_code, source_code, target_domain_code, target_code) DO UPDATE SET
  mapping_type = EXCLUDED.mapping_type,
  confidence = EXCLUDED.confidence,
  provenance = CASE
    WHEN shared.industry_crosswalk.provenance = 'MANUAL'
     AND EXCLUDED.provenance = 'AI_GENERATED'
    THEN shared.industry_crosswalk.provenance
    ELSE EXCLUDED.provenance
  END,
  is_verified = CASE
    WHEN shared.industry_crosswalk.is_verified = true THEN true
    ELSE EXCLUDED.is_verified
  END,
  verified_by = CASE
    WHEN shared.industry_crosswalk.is_verified = true
    THEN shared.industry_crosswalk.verified_by
    ELSE EXCLUDED.verified_by
  END,
  verified_at = CASE
    WHEN shared.industry_crosswalk.is_verified = true
    THEN shared.industry_crosswalk.verified_at
    ELSE EXCLUDED.verified_at
  END,
  notes = EXCLUDED.notes,
  metadata = EXCLUDED.metadata,
  status = EXCLUDED.status,
  updated_at = now(),
  updated_by = EXCLUDED.created_by;
